-- ----------------------------
-- Table structure for ai_message
-- ----------------------------
DROP TABLE IF EXISTS `ai_message`;
CREATE TABLE `ai_message`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `conversation_id` bigint NOT NULL COMMENT '会话ID',
  `role` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息角色',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息内容',
  `reference_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '引用内容',
  `token_usage` int NULL DEFAULT NULL COMMENT 'Token 使用量',
  `feedback` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户反馈: LIKE / DISLIKE',
  `response_ms` int NULL DEFAULT NULL COMMENT '响应耗时(毫秒)',
  `retrieval_score` double NULL DEFAULT NULL COMMENT '最高检索分数',
  `retrieval_hit_count` int NULL DEFAULT NULL COMMENT '检索命中数',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_conversation_id`(`conversation_id` ASC) USING BTREE,
  INDEX `idx_role`(`role` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 124 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI 消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_message
-- ----------------------------
INSERT INTO `ai_message` VALUES (21, 2, 'USER', '工作时间', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 16:46:17');
INSERT INTO `ai_message` VALUES (22, 2, 'ASSISTANT', '根据知识库参考内容，公司的工作时间制度如下：\n\n**一、标准工作时间**\n*   周一至周五，上午 9:00 至下午 18:00。\n*   午休时间为 12:00-13:00。\n\n**二、弹性工作制**\n*   适用于研发和设计岗位，需提前申请。\n*   核心工作时间为 10:00-16:00。\n*   每日工作满 8 小时即可。\n\n**三、加班规定**\n*   加班须提前在 OA 系统提交申请，经主管审批后方可计为有效加班。\n*   加班薪资计算标准：\n    *   工作日加班：按 1.5 倍计薪。\n    *   周末加班：按 2 倍计薪。\n    *   法定节假日加班：按 3 倍计薪。\n*   员工也可选择将加班时间用于调休。\n\n如果您需要了解特定岗位是否适用弹性工作制，或具体的加班申请流程，建议查阅公司内部OA系统或咨询您的主管/人力资源部门。', '考勤与请假制度\n\n一、工作时间\n1. 标准工作时间：周一至周五，上午 9:00 至下午 18:00，午休 12:00-13:00。\n2. 弹性工作制：研发和设计岗位可申请弹性制，核心工作时间为 10:00-16:00，日工作满 8 小时即可。\n3. 加班须提前在 OA 系统提交申请，经主管审批后方可计为有效加班。\n4. 工作日加班按 1.5 倍计薪，周末加班按 2 倍计薪，法定节假日按 3 倍计薪。也可选择调休。\n\n二、打卡规则\n1. 考勤采用人脸识别 + 手机定位双重打卡。\n2. 每天需打上班卡和下班卡，漏打卡视为缺勤。\n3. 漏打卡补卡：每月允许补卡 3 次，须在漏打卡后 24 小时内在 OA 系统申请，主管审批。\n4. 迟到定义：超过上班时间 10 分钟以上视为迟到。迟到超过 30 分钟视为旷工半天。\n5. 每月迟到 3 次以内不处罚（给予口头提醒），超过 3 次扣当月全勤奖。\n\n三、请假类型与天数\n3.1 带薪假期\n- 年假：工龄 1-10 年 5 天，10-20 年 10 天，20 年以上 15 天。\n- 婚假：3 天（晚婚增加 7 天）。\n- 产假：女员工 158 天，男员\n---\n持畅通，收到告警 5 分钟内响应。\n3. 值班交接在每周一上午 10:00 进行，交接内容包括：当前遗留问题、待关注事项、本周变更计划。\n---\n客户常见问题 FAQ\n\n一、账户相关\n\nQ: 如何注册账户？\nA: 访问官网首页点击\"免费注册\"，填写手机号、验证码和密码即可完成注册。企业用户可选择\"企业注册\"，需额外填写企业名称和统一社会信用代码。\n\nQ: 忘记密码怎么办？\nA: 在登录页点击\"忘记密码\"，通过注册手机号接收验证码重置密码。如手机号已更换，请携带身份证联系客服人工重置。\n\nQ: 账户被锁定了怎么办？\nA: 连续 5 次输入错误密码会触发锁定，等待 30 分钟后自动解锁。如紧急使用，可联系客服提前解锁。\n\nQ: 如何修改绑定的手机号？\nA: 登录后进入\"个人中心 > 安全设置 > 修改手机号\"，需验证原手机号后方可更换。\n\nQ: 如何注销账户？\nA: 进入\"个人中心 > 账户设置 > 注销账户\"，确认无未完成订单和余额后提交申请，7 个工作日内处理完成。注销后数据不可恢复。\n\n二、产品相关\n\nQ: 你们的产品有哪些版本？\nA: 我们提供三个版本：\n- 基础版（免费）：支持 3 个用户、1GB 存储空间、基础功能。\n- 专业版（299 元/月）：支持 20 个用户、50GB 存储、高级分析和 API 接口。\n- 企业版', NULL, NULL, NULL, NULL, NULL, '2026-04-22 16:46:26');
INSERT INTO `ai_message` VALUES (23, 2, 'USER', '周末加班如何计算薪资', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 16:47:07');
INSERT INTO `ai_message` VALUES (24, 2, 'ASSISTANT', '根据知识库参考内容，周末加班的薪资计算方式如下：\n\n**周末加班薪资计算**\n*   周末加班按 **2倍** 计薪。\n*   加班须提前在 OA 系统提交申请，并经主管审批后方可计为有效加班。\n*   作为替代方案，员工也可选择将加班时间用于 **调休**。\n\n**重要前提**\n请务必确保加班前已完成OA系统的申请和审批流程，否则可能无法被认定为有效加班并享受相应的薪资补偿或调休。', '考勤与请假制度\n\n一、工作时间\n1. 标准工作时间：周一至周五，上午 9:00 至下午 18:00，午休 12:00-13:00。\n2. 弹性工作制：研发和设计岗位可申请弹性制，核心工作时间为 10:00-16:00，日工作满 8 小时即可。\n3. 加班须提前在 OA 系统提交申请，经主管审批后方可计为有效加班。\n4. 工作日加班按 1.5 倍计薪，周末加班按 2 倍计薪，法定节假日按 3 倍计薪。也可选择调休。\n\n二、打卡规则\n1. 考勤采用人脸识别 + 手机定位双重打卡。\n2. 每天需打上班卡和下班卡，漏打卡视为缺勤。\n3. 漏打卡补卡：每月允许补卡 3 次，须在漏打卡后 24 小时内在 OA 系统申请，主管审批。\n4. 迟到定义：超过上班时间 10 分钟以上视为迟到。迟到超过 30 分钟视为旷工半天。\n5. 每月迟到 3 次以内不处罚（给予口头提醒），超过 3 次扣当月全勤奖。\n\n三、请假类型与天数\n3.1 带薪假期\n- 年假：工龄 1-10 年 5 天，10-20 年 10 天，20 年以上 15 天。\n- 婚假：3 天（晚婚增加 7 天）。\n- 产假：女员工 158 天，男员\n---\n持畅通，收到告警 5 分钟内响应。\n3. 值班交接在每周一上午 10:00 进行，交接内容包括：当前遗留问题、待关注事项、本周变更计划。\n---\n复处理方案。\n3. 重大投诉由售后经理直接对接处理，确保 48 小时内给出解决方案。\n4. 客户满意度回访在工单关闭后 3 天内进行。\n\n七、常见问题\nQ1: 如何查询产品是否在质保期内？\nA1: 登录官网「我的设备」页面输入产品序列号即可查询，或致电客服热线查询。\n\nQ2: 维修期间有备用机吗？\nA2: 企业客户享有免费备用机服务，个人客户可申请租用备用机（押金 500 元）。\n\nQ3: 海外购买的产品可以在国内保修吗？\nA3: 全球联保产品可以，请携带购买凭证到国内授权服务中心。\n\nQ4: 过保维修大概多少钱？\nA4: 检测费 50 元，维修费根据故障类型 100-500 元不等，配件费另计，维修前会报价确认。', NULL, NULL, NULL, NULL, NULL, '2026-04-22 16:47:12');
INSERT INTO `ai_message` VALUES (25, 2, 'USER', '试用期说明', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 16:52:08');
INSERT INTO `ai_message` VALUES (26, 2, 'ASSISTANT', '## 试用期说明\n\n根据您提供的知识库参考内容，其中**未包含**关于“试用期”的具体规定，例如试用期时长、考核标准、薪酬待遇或转正流程等。\n\n### 建议您通过以下途径获取准确信息：\n1.  **查阅劳动合同**：您的试用期条款应已在与公司签订的劳动合同中明确约定。\n2.  **咨询人力资源部门**：HR部门是获取公司统一人事政策（包括试用期、薪酬福利等）的最权威渠道。\n3.  **查看公司内部员工手册或OA系统**：完整的公司制度通常会在内部知识库或办公系统中发布。\n\n### 基于通用知识的一般性说明（仅供参考）：\n- **目的**：试用期是供用人单位与劳动者相互考察、双向选择的期限。\n- **时长**：根据中国《劳动合同法》，劳动合同期限三个月以上不满一年的，试用期不得超过一个月；一年以上不满三年的，不得超过二个月；三年以上固定期限和无固定期限的劳动合同，不得超过六个月。\n- **薪酬**：劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。\n- **考核与转正**：通常会有明确的考核流程，请在入职时与主管或HR确认具体的转正条件和评估时间。\n\n为了获得适用于您个人情况的准确说明，请务必依据上述建议查询官方文件或直接咨询相关负责人。', '持畅通，收到告警 5 分钟内响应。\n3. 值班交接在每周一上午 10:00 进行，交接内容包括：当前遗留问题、待关注事项、本周变更计划。\n---\n考勤与请假制度\n\n一、工作时间\n1. 标准工作时间：周一至周五，上午 9:00 至下午 18:00，午休 12:00-13:00。\n2. 弹性工作制：研发和设计岗位可申请弹性制，核心工作时间为 10:00-16:00，日工作满 8 小时即可。\n3. 加班须提前在 OA 系统提交申请，经主管审批后方可计为有效加班。\n4. 工作日加班按 1.5 倍计薪，周末加班按 2 倍计薪，法定节假日按 3 倍计薪。也可选择调休。\n\n二、打卡规则\n1. 考勤采用人脸识别 + 手机定位双重打卡。\n2. 每天需打上班卡和下班卡，漏打卡视为缺勤。\n3. 漏打卡补卡：每月允许补卡 3 次，须在漏打卡后 24 小时内在 OA 系统申请，主管审批。\n4. 迟到定义：超过上班时间 10 分钟以上视为迟到。迟到超过 30 分钟视为旷工半天。\n5. 每月迟到 3 次以内不处罚（给予口头提醒），超过 3 次扣当月全勤奖。\n\n三、请假类型与天数\n3.1 带薪假期\n- 年假：工龄 1-10 年 5 天，10-20 年 10 天，20 年以上 15 天。\n- 婚假：3 天（晚婚增加 7 天）。\n- 产假：女员工 158 天，男员\n---\n项目管理规范\n\n一、项目立项\n1. 所有项目启动前须提交《项目立项申请书》，经部门总监审批后方可启动。\n2. 立项申请内容包括：项目背景、目标、范围、预算、人员需求、里程碑计划。\n3. 预算超过 50 万元的项目需经总经理审批。\n4. 立项通过后由 PMO 分配项目编号并在项目管理系统中创建项目空间。\n\n二、项目角色与职责\n1. 项目经理（PM）：负责项目整体规划、进度跟踪、风险管控和干系人沟通。\n2. 产品经理（PD）：负责需求分析、产品设计和验收标准制定。\n3. 技术负责人（TL）：负责技术方案选型、架构设计和代码质量把控。\n4. 开发工程师：按照技术方案完成编码、单元测试和代码评审。\n5. 测试工程师：制定测试计划、编写测试用例、执行测试并输出报告。\n6. 运维工程师：负责环境搭建、部署上线和运行监控。\n\n三、需求管理\n1. 需求来源包括：客户反馈、产品规划、运营建议、技术债务。\n2. 所有需求须录入需求管理系统，包含：优先级、描述、验收标准、预估工时。\n3. 需求优先级分为 P0（紧急）、P1（高）、P2（中）、P3（低）。\n4. 需求变更须提交变更申请，经项目经理和产品经理双', NULL, 'LIKE', NULL, NULL, NULL, '2026-04-22 16:52:21');
INSERT INTO `ai_message` VALUES (27, 3, 'USER', '有没有***行为', NULL, NULL, NULL, NULL, NULL, NULL, '2026-04-22 17:36:35');
INSERT INTO `ai_message` VALUES (28, 3, 'ASSISTANT', '根据您提供的知识库参考内容，我无法找到与“***行为”直接相关的具体规定或说明。知识库内容主要涉及客户服务流程、考勤与请假制度，并未明确界定或列举哪些行为属于“***行为”。\n\n为了能更准确地回答您的问题，建议您：\n1.  **明确具体行为**：请提供您所关心的具体行为描述，以便在相关制度中查找对应规定。\n2.  **参考相关制度**：判断该行为可能涉及公司哪方面的管理规定（如：**《员工手册》**、**信息安全规范》**、**《商业行为准则》**等），然后查阅对应文件。\n3.  **咨询相关部门**：对于行为性质的最终认定，建议向公司**人力资源部**或**合规部**进行正式咨询。\n\n如果您能提供更具体的行为描述，我将尽力为您在现有知识库中查找相关信息。', '复处理方案。\n3. 重大投诉由售后经理直接对接处理，确保 48 小时内给出解决方案。\n4. 客户满意度回访在工单关闭后 3 天内进行。\n\n七、常见问题\nQ1: 如何查询产品是否在质保期内？\nA1: 登录官网「我的设备」页面输入产品序列号即可查询，或致电客服热线查询。\n\nQ2: 维修期间有备用机吗？\nA2: 企业客户享有免费备用机服务，个人客户可申请租用备用机（押金 500 元）。\n\nQ3: 海外购买的产品可以在国内保修吗？\nA3: 全球联保产品可以，请携带购买凭证到国内授权服务中心。\n\nQ4: 过保维修大概多少钱？\nA4: 检测费 50 元，维修费根据故障类型 100-500 元不等，配件费另计，维修前会报价确认。\n---\n持畅通，收到告警 5 分钟内响应。\n3. 值班交接在每周一上午 10:00 进行，交接内容包括：当前遗留问题、待关注事项、本周变更计划。\n---\n考勤与请假制度\n\n一、工作时间\n1. 标准工作时间：周一至周五，上午 9:00 至下午 18:00，午休 12:00-13:00。\n2. 弹性工作制：研发和设计岗位可申请弹性制，核心工作时间为 10:00-16:00，日工作满 8 小时即可。\n3. 加班须提前在 OA 系统提交申请，经主管审批后方可计为有效加班。\n4. 工作日加班按 1.5 倍计薪，周末加班按 2 倍计薪，法定节假日按 3 倍计薪。也可选择调休。\n\n二、打卡规则\n1. 考勤采用人脸识别 + 手机定位双重打卡。\n2. 每天需打上班卡和下班卡，漏打卡视为缺勤。\n3. 漏打卡补卡：每月允许补卡 3 次，须在漏打卡后 24 小时内在 OA 系统申请，主管审批。\n4. 迟到定义：超过上班时间 10 分钟以上视为迟到。迟到超过 30 分钟视为旷工半天。\n5. 每月迟到 3 次以内不处罚（给予口头提醒），超过 3 次扣当月全勤奖。\n\n三、请假类型与天数\n3.1 带薪假期\n- 年假：工龄 1-10 年 5 天，10-20 年 10 天，20 年以上 15 天。\n- 婚假：3 天（晚婚增加 7 天）。\n- 产假：女员工 158 天，男员', NULL, 'DISLIKE', 9819, NULL, NULL, '2026-04-22 17:36:45');
