INSERT INTO `ai_message` VALUES (111, 10, 'ASSISTANT', '根据知识库中的《AI 知识工单平台 — 产品使用手册》，该平台的简介如下：\n\n**AI 知识工单平台**是一款面向企业的智能客服与知识管理系统。平台整合了以下三大核心模块，旨在帮助企业高效处理客户咨询、沉淀业务知识、提升售后服务质量：\n\n1.  **知识库管理**：支持上传和管理企业知识文档。\n2.  **AI 智能问答**：基于知识库内容，提供智能化的问答服务。\n3.  **工单辅助处理**：辅助客服人员处理客户问题，提升工单处理效率。\n\n如果您想了解更详细的功能，例如如何登录、上传文档或使用AI问答，可以随时提出具体问题。', NULL, NULL, NULL, 24868, NULL, NULL, '2026-04-22 22:27:36');
