INSERT INTO `ai_message` VALUES (121, 11, 'ASSISTANT', '我无法直接获取实时天气信息。你可以通过以下方式查询：\n\n1. **手机天气应用**：打开手机自带的天气应用（如苹果天气、华为天气等）。\n2. **搜索引擎**：在浏览器搜索“天气+城市名”（例如“北京天气”）。\n3. **天气网站**：访问中国天气网（www.weather.com.cn）或国际平台如AccuWeather。\n4. **语音助手**：对手机说“嘿Siri/小爱同学，明天天气怎么样？”\n\n如果需要查询具体城市，可以告诉我你的位置，我可以帮你分析近期天气趋势或提供生活建议哦！ 🌤️', NULL, NULL, NULL, 14540, NULL, NULL, '2026-04-22 22:34:01');
