-- ----------------------------
-- Table structure for ai_model_config
-- ----------------------------
DROP TABLE IF EXISTS `ai_model_config`;
CREATE TABLE `ai_model_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '配置ID',
  `model_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型标识',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型显示名',
  `provider` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'OPENAI' COMMENT '提供商',
  `base_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'API 地址',
  `api_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'API Key',
  `model_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '模型ID',
  `temperature` double NULL DEFAULT 0.7,
  `max_tokens` int NULL DEFAULT 2048,
  `enabled` tinyint NOT NULL DEFAULT 1,
  `is_default` tinyint NOT NULL DEFAULT 0 COMMENT '是否默认模型',
  `sort_order` int NULL DEFAULT 0,
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_model_key`(`model_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI 模型配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_model_config
-- ----------------------------

-- ----------------------------
-- Table structure for ai_prompt_config
-- ----------------------------
DROP TABLE IF EXISTS `ai_prompt_config`;
CREATE TABLE `ai_prompt_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `config_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `config_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `enabled` tinyint NOT NULL DEFAULT 1,
  `sort_order` int NOT NULL DEFAULT 0,
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_config_key`(`config_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI提示词配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_prompt_config
-- ----------------------------
INSERT INTO `ai_prompt_config` VALUES (1, 'SYSTEM_PROMPT', '系统角色提示词', '你是「AI 知识工单平台」的智能助手，系统已通过 LangChain4j 成功接入大语言模型，你现在完全可用。\n请直接、专业地回答用户问题。如果下方提供了知识库参考内容，请优先基于这些内容回答；如果没有提供参考内容，请根据你自身知识尽力回答。\n不要说自己尚未接入或不可用，你已经在线并正常工作。', '定义 AI 助手的角色和行为规范', 1, 1, '2026-04-22 17:10:16', '2026-04-22 17:10:16');
INSERT INTO `ai_prompt_config` VALUES (2, 'FORMAT_PROMPT', '输出格式提示词', '【输出格式要求】请使用 Markdown 格式输出回答：\n- 用 ## 或 ### 作为小标题\n- 用有序列表（1. 2. 3.）或无序列表（- ）组织要点\n- 关键信息用 **加粗** 强调\n- 不同段落之间保留空行', '控制 AI 回答的输出格式', 1, 2, '2026-04-22 17:10:16', '2026-04-22 17:10:16');
INSERT INTO `ai_prompt_config` VALUES (3, 'CONTEXT_TEMPLATE', '知识库上下文模板', '【知识库参考内容】\n{context}', '知识库检索结果的包装模板，{context} 为占位符', 1, 3, '2026-04-22 17:10:16', '2026-04-22 17:10:16');
INSERT INTO `ai_prompt_config` VALUES (4, 'HISTORY_TEMPLATE', '对话历史模板', '【对话历史】\n{history}', '历史对话的包装模板，{history} 为占位符', 1, 4, '2026-04-22 17:10:16', '2026-04-22 17:10:16');
INSERT INTO `ai_prompt_config` VALUES (5, 'QUESTION_TEMPLATE', '用户问题模板', '【用户问题】\n{question}\n\n请用中文回答：', '用户问题的包装模板，{question} 为占位符', 1, 5, '2026-04-22 17:10:16', '2026-04-22 17:10:16');

-- ----------------------------
-- Table structure for kb_category
-- ----------------------------
DROP TABLE IF EXISTS `kb_category`;
CREATE TABLE `kb_category`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类描述',
  `sort_order` int NULL DEFAULT 0,
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_name`(`name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '知识库分类表' ROW_FORMAT = Dynamic;

