-- ----------------------------
-- Table structure for kb_chunk
-- ----------------------------
DROP TABLE IF EXISTS `kb_chunk`;
CREATE TABLE `kb_chunk`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '切片ID',
  `document_id` bigint NOT NULL COMMENT '文档ID',
  `chunk_index` int NOT NULL COMMENT '切片序号',
  `chunk_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '切片内容',
  `char_count` int NOT NULL DEFAULT 0 COMMENT '字符数',
  `vector_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '向量状态',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_document_id`(`document_id` ASC) USING BTREE,
  INDEX `idx_vector_status`(`vector_status` ASC) USING BTREE,
  FULLTEXT INDEX `ft_chunk_text` (`chunk_text`) WITH PARSER ngram
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '知识库切片表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of kb_chunk
-- ----------------------------
INSERT INTO `kb_chunk` VALUES (1, 1, 0, 'AI 知识工单平台 — 产品使用手册\n\n一、平台简介\nAI 知识工单平台是一款面向企业的智能客服与知识管理系统。平台整合了知识库管理、AI 智能问答和工单辅助处理三大核心模块，帮助企业高效处理客户咨询、沉淀业务知识、提升售后服务质量。\n\n二、系统登录与账户管理\n1. 打开浏览器访问平台地址，输入用户名和密码后点击\"登录\"。\n2. 首次登录建议修改默认密码，进入\"系统管理 > 个人中心\"修改。\n3. 忘记密码请联系管理员重置。\n4. 系统支持多角色权限：管理员可管理所有模块，普通用户仅可使用知识问答和提交工单。\n\n三、知识库管理\n1. 文档上传：支持 TXT、MD、CSV 等文本文件，上传后系统自动解析文本内容。\n2. 文本切分：系统将文档按 500 字为一个切片进行分割，相邻切片之间有 50 字重叠以保证语义连贯。\n3. 向量索引：切片文本通过 AllMiniLM 模型转换为向量，存入内存向量库供检索使用。\n4. 文档管理：支持按名称、分类、解析状态搜索，支持编辑和删除操作。\n5. 切片查看：点击文档可查看其所有切片内容和向量化状态。\n\n四、AI 智能问答\n1. 创建会话：点击\"新建会', 500, 'PENDING', '2026-04-22 16:24:12');
INSERT INTO `kb_chunk` VALUES (2, 1, 1, '查看：点击文档可查看其所有切片内容和向量化状态。\n\n四、AI 智能问答\n1. 创建会话：点击\"新建会话\"按钮创建一个新的对话。\n2. 提问方式：在输入框中输入问题，按 Ctrl+Enter 或点击\"发送\"按钮。\n3. RAG 检索：系统会将用户问题转换为向量，在知识库中检索最相关的 3 个切片作为参考上下文。\n4. 模型回答：系统将检索到的知识上下文、对话历史和用户问题组装成 Prompt，发送给 DeepSeek 大模型生成回答。\n5. 多轮对话：系统保留最近 10 条对话历史，支持上下文连续追问。\n6. 如果知识库中没有相关内容，AI 会如实告知而非编造答案。\n\n五、工单辅助\n1. 新增工单：填写工单标题、内容、客户名称、分类和优先级后提交。\n2. AI 自动辅助：提交工单后，系统会异步调用 DeepSeek 模型自动生成以下内容：\n   - 问题摘要：一两句话概括工单核心问题\n   - 回复建议：给客户的专业、友好的回复草稿\n   - 处理建议：给内部处理人员的操作步骤建议\n3. 重新生成：在工单详情页点击\"重新生成 AI 辅助\"按钮可重新调用模型生成。\n4. 工单状态流转：待处', 500, 'PENDING', '2026-04-22 16:24:12');
INSERT INTO `kb_chunk` VALUES (3, 1, 2, '重新生成：在工单详情页点击\"重新生成 AI 辅助\"按钮可重新调用模型生成。\n4. 工单状态流转：待处理 → 处理中 → 已解决 → 已关闭。\n5. 工单搜索：支持按标题、优先级、状态进行筛选。\n\n六、常见问题 FAQ\nQ1: 上传文档后显示\"解析失败\"怎么办？\nA1: 请确认文件编码为 UTF-8 格式，目前仅支持纯文本类文件（TXT、MD、CSV）。\n\nQ2: AI 回答不准确怎么优化？\nA2: 建议上传更多相关领域的知识文档，知识库内容越丰富，检索命中率越高，回答质量越好。\n\nQ3: 工单的 AI 辅助内容为空？\nA3: AI 辅助是异步生成的，提交后需等待几秒钟，在工单详情页点击\"刷新\"按钮查看。\n\nQ4: 系统支持哪些大模型？\nA4: 系统通过 LangChain4j 集成 OpenAI 兼容 API，可对接 DeepSeek、通义千问、GPT 等任何兼容接口的大模型，只需修改 application.yml 中的 base-url 和 api-key。\n\nQ5: 向量库数据会丢失吗？\nA5: 当前使用内存向量库（InMemoryEmbeddingStore），服务重启后需重新', 500, 'PENDING', '2026-04-22 16:24:12');
INSERT INTO `kb_chunk` VALUES (4, 1, 3, '失吗？\nA5: 当前使用内存向量库（InMemoryEmbeddingStore），服务重启后需重新索引。生产环境建议替换为持久化向量库（如 Milvus、Qdrant）。\n\n七、技术架构\n- 前端：Vue 3 + Element Plus + Vite + Axios\n- 后端：Spring Boot 3.2 + MyBatis + LangChain4j\n- 数据库：MySQL 8.0\n- 大模型：DeepSeek（通过 OpenAI 兼容 API 调用）\n- 向量模型：AllMiniLM-L6-V2（本地 ONNX 推理，无需 GPU）\n- 向量存储：InMemoryEmbeddingStore（演示用）\n\n八、联系与支持\n如有使用问题，请通过工单系统提交反馈，或联系平台管理员获取技术支持。', 353, 'PENDING', '2026-04-22 16:24:12');
INSERT INTO `kb_chunk` VALUES (5, 2, 0, '员工入职指南\n\n一、入职前准备\n1. 收到录用通知后，请在 3 个工作日内确认入职意向并回复 HR。\n2. 准备以下材料：身份证原件及复印件、学历证书原件及复印件、近期免冠照片 2 张、前单位离职证明、银行卡信息（工资卡）。\n3. 体检报告需在入职前一周完成，可前往公司指定的体检机构或三甲医院。\n\n二、入职当天流程\n1. 上午 9:00 到达公司前台，HR 专员引导签到。\n2. 填写《员工信息登记表》《保密协议》《劳动合同》等文件。\n3. 领取工牌、门禁卡和办公用品。\n4. IT 部门为新员工开通企业邮箱、VPN、内部系统账号（OA、ERP、CRM）。\n5. 部门主管安排工位并介绍团队成员。\n\n三、试用期说明\n1. 试用期一般为 3 个月，特殊岗位最长不超过 6 个月。\n2. 试用期内享有社保和公积金待遇，薪资为转正后的 80%。\n3. 试用期满前两周，部门主管与 HR 共同进行转正评估。\n4. 转正评估维度包括：工作能力、团队协作、学习态度、出勤情况。\n\n四、培训安排\n1. 入职第一周为集中培训期，内容包括：\n   - 公司文化与发展历史\n   - 组织架构与部门职责\n   - 产品', 500, 'PENDING', '2026-04-22 16:45:25');
INSERT INTO `kb_chunk` VALUES (6, 2, 1, '为集中培训期，内容包括：\n   - 公司文化与发展历史\n   - 组织架构与部门职责\n   - 产品与业务线介绍\n   - 安全生产与信息安全规范\n   - 内部系统使用培训\n2. 部门内部会安排导师（Mentor）一对一辅导，为期 1 个月。\n3. 培训结束后需完成在线考核，成绩计入试用期评估。\n\n五、薪酬与福利\n1. 工资发放日为每月 15 日，通过银行转账。\n2. 社保五险一金按国家标准缴纳。\n3. 福利包括：年度体检、节日礼品、生日关怀、团建活动。\n4. 年假：工龄 1-10 年享 5 天，10-20 年享 10 天，20 年以上享 15 天。\n\n六、常见问题\nQ1: 入职日期可以协商调整吗？\nA1: 可以，请在确认入职时与 HR 协商，通常可前后调整 1-2 周。\n\nQ2: 试用期内可以请假吗？\nA2: 可以，按照公司考勤制度正常申请，但频繁请假会影响转正评估。\n\nQ3: 工牌丢失怎么办？\nA3: 请联系行政部补办，补办费用 30 元，3 个工作日内完成。', 439, 'PENDING', '2026-04-22 16:45:25');
INSERT INTO `kb_chunk` VALUES (7, 3, 0, 'IT 运维故障处理手册\n\n一、故障分级标准\nP0（紧急）：核心业务系统全面瘫痪，影响全部用户，需 15 分钟内响应，2 小时内恢复。\nP1（严重）：核心功能不可用但有替代方案，影响大部分用户，需 30 分钟内响应，4 小时内恢复。\nP2（一般）：非核心功能异常，影响部分用户，需 2 小时内响应，24 小时内恢复。\nP3（轻微）：界面显示问题、文案错误等，影响极小，需 8 小时内响应，72 小时内修复。\n\n二、故障报告流程\n1. 发现故障后，第一时间在工单系统中提交故障工单，选择\"IT运维\"分类。\n2. 工单标题格式：【PX】系统名称 - 故障简述，例如【P1】CRM系统 - 订单查询超时。\n3. 工单内容需包含：故障现象、影响范围、复现步骤、截图或日志。\n4. 运维值班人员收到工单后立即评估并确认故障等级。\n5. P0/P1 故障同时电话通知运维经理和技术总监。\n\n三、常见故障及处理方法\n\n3.1 服务器无法访问\n可能原因：网络中断、服务器宕机、防火墙规则异常。\n处理步骤：\n1. 使用 ping 命令测试网络连通性。\n2. 检查云平台控制台，确认实例运行状态。\n3. 远程登录服务器检查', 500, 'PENDING', '2026-04-22 16:45:30');
INSERT INTO `kb_chunk` VALUES (8, 3, 1, 'ping 命令测试网络连通性。\n2. 检查云平台控制台，确认实例运行状态。\n3. 远程登录服务器检查系统日志（/var/log/syslog 或 /var/log/messages）。\n4. 检查防火墙规则和安全组配置。\n5. 如服务器宕机，尝试重启；如无法恢复，启用备机并通知团队。\n\n3.2 数据库连接超时\n可能原因：连接数耗尽、慢查询阻塞、磁盘空间不足。\n处理步骤：\n1. 查看数据库连接池状态：SHOW PROCESSLIST。\n2. 检查慢查询日志，终止长时间运行的查询：KILL <process_id>。\n3. 检查磁盘空间：df -h，如空间不足立即清理日志或扩容。\n4. 检查数据库参数：max_connections、wait_timeout 是否合理。\n5. 临时措施：重启数据库连接池或重启应用服务。\n\n3.3 应用接口响应缓慢\n可能原因：代码性能问题、外部依赖超时、JVM内存不足。\n处理步骤：\n1. 查看应用监控：CPU、内存、GC 频率。\n2. 检查接口调用链路，定位耗时最长的环节。\n3. 如果是 JVM 内存问题，导出 heap dump 后重启应用。\n4. 如果是', 500, 'PENDING', '2026-04-22 16:45:30');
INSERT INTO `kb_chunk` VALUES (9, 3, 2, '时最长的环节。\n3. 如果是 JVM 内存问题，导出 heap dump 后重启应用。\n4. 如果是外部依赖超时，检查第三方服务状态并启用熔断降级。\n5. 必要时水平扩容增加应用实例。\n\n3.4 磁盘空间告警\n可能原因：日志文件过大、临时文件未清理、数据增长超出预期。\n处理步骤：\n1. 使用 du -sh /path/* 找到占用最大的目录。\n2. 清理过期日志：find /var/log -name \"*.log\" -mtime +30 -delete。\n3. 清理 Docker 无用镜像和容器：docker system prune -f。\n4. 如磁盘频繁告警，申请扩容或调整日志轮转策略。\n\n四、故障复盘\n1. P0/P1 故障恢复后 48 小时内必须召开复盘会议。\n2. 复盘报告包含：时间线、根因分析、影响评估、改进措施。\n3. 改进措施需明确责任人和完成日期，录入项目管理系统跟踪。\n\n五、值班制度\n1. 运维团队实行 7×24 小时轮值制度，每人值班一周。\n2. 值班期间手机保持畅通，收到告警 5 分钟内响应。\n3. 值班交接在每周一上午 10:00 进行，交接内容包括：当前', 500, 'PENDING', '2026-04-22 16:45:30');
INSERT INTO `kb_chunk` VALUES (10, 3, 3, '持畅通，收到告警 5 分钟内响应。\n3. 值班交接在每周一上午 10:00 进行，交接内容包括：当前遗留问题、待关注事项、本周变更计划。', 68, 'PENDING', '2026-04-22 16:45:30');
INSERT INTO `kb_chunk` VALUES (11, 4, 0, '产品售后服务政策\n\n一、服务承诺\n本公司对所有正式销售的产品提供完善的售后服务保障。我们承诺以专业、高效、真诚的态度处理每一位客户的问题，确保客户满意度达到 95% 以上。\n\n二、质保期限\n1. 硬件产品：自购买之日起享受 24 个月免费质保。\n2. 软件产品：自激活之日起享受 12 个月免费升级和技术支持。\n3. 定制开发项目：自验收之日起享受 6 个月免费维护期，之后可签订年度维保合同。\n4. 消耗类配件（电池、墨盒等）：质保期为 3 个月。\n\n三、服务范围\n3.1 免费服务范围\n- 产品在质保期内出现的非人为故障。\n- 软件 Bug 修复和功能补丁更新。\n- 电话/远程技术支持和使用指导。\n- 每年一次免费系统巡检服务（企业客户）。\n\n3.2 收费服务范围\n- 超出质保期的维修（按实际工时和配件收费）。\n- 人为损坏、进液、摔落造成的故障。\n- 非授权机构拆修导致的问题。\n- 软件定制化需求和二次开发。\n- 现场上门服务（路费按实际产生收取）。\n\n四、服务流程\n1. 客户通过以下渠道提交售后请求：\n   - 客服热线：400-888-9999（工作日 9:00-18:00）\n  ', 500, 'PENDING', '2026-04-22 16:45:34');
INSERT INTO `kb_chunk` VALUES (12, 4, 1, '道提交售后请求：\n   - 客服热线：400-888-9999（工作日 9:00-18:00）\n   - 在线工单系统（7×24 小时）\n   - 企业微信客服\n2. 客服人员在 2 小时内响应并创建工单。\n3. 技术人员远程诊断，80% 以上的问题可远程解决。\n4. 需要返修的产品，客户寄回后 5 个工作日内完成维修并寄回。\n5. 需要上门服务的，工程师 48 小时内到达现场（偏远地区 72 小时）。\n6. 服务完成后客户确认并评价，工单关闭。\n\n五、退换货政策\n1. 7 天无理由退货：自签收之日起 7 天内，产品未拆封可全额退款。\n2. 15 天换货：自签收之日起 15 天内，产品存在质量问题可免费更换同型号新品。\n3. 退换货流程：联系客服 → 审核通过 → 寄回产品 → 质检确认 → 退款/发货。\n4. 退款时效：审核通过后 3-5 个工作日退回原支付渠道。\n\n六、投诉与升级\n1. 如对服务结果不满意，可拨打投诉专线 400-888-9998。\n2. 投诉处理时限：24 小时内回复处理方案。\n3. 重大投诉由售后经理直接对接处理，确保 48 小时内给出解决方案。\n4. 客户满意', 500, 'PENDING', '2026-04-22 16:45:34');
INSERT INTO `kb_chunk` VALUES (13, 4, 2, '复处理方案。\n3. 重大投诉由售后经理直接对接处理，确保 48 小时内给出解决方案。\n4. 客户满意度回访在工单关闭后 3 天内进行。\n\n七、常见问题\nQ1: 如何查询产品是否在质保期内？\nA1: 登录官网「我的设备」页面输入产品序列号即可查询，或致电客服热线查询。\n\nQ2: 维修期间有备用机吗？\nA2: 企业客户享有免费备用机服务，个人客户可申请租用备用机（押金 500 元）。\n\nQ3: 海外购买的产品可以在国内保修吗？\nA3: 全球联保产品可以，请携带购买凭证到国内授权服务中心。\n\nQ4: 过保维修大概多少钱？\nA4: 检测费 50 元，维修费根据故障类型 100-500 元不等，配件费另计，维修前会报价确认。', 311, 'PENDING', '2026-04-22 16:45:34');
INSERT INTO `kb_chunk` VALUES (14, 5, 0, '企业信息安全管理制度\n\n一、总则\n为保障公司信息资产安全，防范信息泄露、篡改和丢失风险，依据《网络安全法》《数据安全法》《个人信息保护法》等法律法规，制定本制度。本制度适用于公司全体员工、外包人员及合作方。\n\n二、账号与密码管理\n1. 所有系统账号由 IT 部门统一创建和分配，严禁私自创建或共享账号。\n2. 密码要求：最少 8 位，包含大小写字母、数字和特殊字符。\n3. 密码有效期 90 天，到期后系统强制修改。\n4. 连续输错密码 5 次，账号自动锁定 30 分钟。\n5. 离职员工账号需在离职当天由 IT 部门禁用，3 天内彻底删除。\n6. 严禁将账号密码写在纸上贴在电脑旁或通过即时通讯工具明文发送。\n\n三、网络安全\n1. 公司网络划分为办公区、开发区、生产区和访客区，各区域之间进行网络隔离。\n2. 所有服务器必须部署防火墙，仅开放业务必需端口。\n3. 员工不得在公司网络中使用未经授权的 VPN、代理或翻墙工具。\n4. 禁止私自搭建 Wi-Fi 热点或将私人设备接入公司内网。\n5. IT 部门每季度进行一次网络安全扫描和漏洞评估。\n6. 发现异常网络行为（如大量数据外传、异常登录）需', 500, 'PENDING', '2026-04-22 16:45:38');
INSERT INTO `kb_chunk` VALUES (15, 5, 1, 'T 部门每季度进行一次网络安全扫描和漏洞评估。\n6. 发现异常网络行为（如大量数据外传、异常登录）需立即上报。\n\n四、数据安全\n4.1 数据分级\n- 绝密数据：核心算法、客户交易数据、财务报表，仅限高管和授权人员访问。\n- 机密数据：产品设计文档、源代码、合同，仅限相关部门访问。\n- 内部数据：内部通知、会议纪要、培训资料，全员可访问但不得外传。\n- 公开数据：官网内容、宣传资料，可对外发布。\n\n4.2 数据保护措施\n1. 绝密和机密数据传输必须加密（TLS 1.2 以上）。\n2. 数据库敏感字段须脱敏存储（如手机号、身份证号、银行卡号）。\n3. 生产环境数据严禁导出到开发/测试环境，需使用脱敏后的模拟数据。\n4. USB 接口默认禁用，如有数据拷贝需求须经部门主管和信息安全负责人双重审批。\n5. 关键业务数据每天自动备份，备份数据异地存储，保留 90 天。\n\n五、终端安全\n1. 所有办公电脑必须安装公司指定的杀毒软件并保持实时更新。\n2. 操作系统和应用程序须及时安装安全补丁，IT 部门统一推送。\n3. 禁止安装盗版软件、游戏、P2P 下载工具等非工作必需软件。\n4. 笔记本电脑离开', 500, 'PENDING', '2026-04-22 16:45:38');
INSERT INTO `kb_chunk` VALUES (16, 5, 2, '门统一推送。\n3. 禁止安装盗版软件、游戏、P2P 下载工具等非工作必需软件。\n4. 笔记本电脑离开工位须锁屏（Windows: Win+L），离开办公区须带走或锁入柜中。\n5. 远程办公须通过公司 VPN 接入，不得在公共 Wi-Fi 下直接访问内部系统。\n\n六、邮件安全\n1. 不得使用个人邮箱收发工作邮件。\n2. 发送外部邮件附带敏感数据时须加密并设置密码，密码通过其他渠道告知收件人。\n3. 收到可疑邮件（钓鱼邮件）不要点击链接或下载附件，立即转发至 security@company.com 报告。\n4. 群发邮件涉及外部收件人时使用密送（BCC），保护客户隐私。\n\n七、安全事件处置\n1. 发现或疑似信息安全事件，员工须在 30 分钟内向 IT 部门报告。\n2. IT 部门进行初步评估和应急处置，1 小时内上报信息安全负责人。\n3. 重大安全事件（数据泄露、勒索攻击等）需启动应急预案，成立专项处置小组。\n4. 安全事件处置完成后 7 天内提交事件报告，包含根因分析和整改措施。\n\n八、违规处罚\n1. 一般违规（如未锁屏、弱密码）：口头警告，记入绩效。\n2. 严重违规（如数据外泄、私接', 500, 'PENDING', '2026-04-22 16:45:38');
INSERT INTO `kb_chunk` VALUES (17, 5, 3, '违规处罚\n1. 一般违规（如未锁屏、弱密码）：口头警告，记入绩效。\n2. 严重违规（如数据外泄、私接外网）：书面警告并扣除当月绩效奖金。\n3. 重大违规（如故意泄露机密数据）：解除劳动合同，保留追究法律责任的权利。\n\n九、安全培训\n1. 新员工入职必须完成信息安全培训并通过考核。\n2. 全员每年参加一次信息安全意识培训。\n3. IT 和研发人员每半年参加一次安全技术专项培训。\n4. 公司每年组织一次钓鱼邮件模拟演练。', 210, 'PENDING', '2026-04-22 16:45:38');
INSERT INTO `kb_chunk` VALUES (18, 6, 0, '项目管理规范\n\n一、项目立项\n1. 所有项目启动前须提交《项目立项申请书》，经部门总监审批后方可启动。\n2. 立项申请内容包括：项目背景、目标、范围、预算、人员需求、里程碑计划。\n3. 预算超过 50 万元的项目需经总经理审批。\n4. 立项通过后由 PMO 分配项目编号并在项目管理系统中创建项目空间。\n\n二、项目角色与职责\n1. 项目经理（PM）：负责项目整体规划、进度跟踪、风险管控和干系人沟通。\n2. 产品经理（PD）：负责需求分析、产品设计和验收标准制定。\n3. 技术负责人（TL）：负责技术方案选型、架构设计和代码质量把控。\n4. 开发工程师：按照技术方案完成编码、单元测试和代码评审。\n5. 测试工程师：制定测试计划、编写测试用例、执行测试并输出报告。\n6. 运维工程师：负责环境搭建、部署上线和运行监控。\n\n三、需求管理\n1. 需求来源包括：客户反馈、产品规划、运营建议、技术债务。\n2. 所有需求须录入需求管理系统，包含：优先级、描述、验收标准、预估工时。\n3. 需求优先级分为 P0（紧急）、P1（高）、P2（中）、P3（低）。\n4. 需求变更须提交变更申请，经项目经理和产品经理双', 500, 'PENDING', '2026-04-22 16:45:47');
INSERT INTO `kb_chunk` VALUES (19, 6, 1, '（紧急）、P1（高）、P2（中）、P3（低）。\n4. 需求变更须提交变更申请，经项目经理和产品经理双签后生效。\n5. 需求冻结后不再接受变更，紧急变更需总监特批并评估影响。\n\n四、开发流程\n1. 代码分支策略采用 Git Flow：main（生产）、develop（开发）、feature/*（功能）、hotfix/*（修复）。\n2. 所有代码提交须关联需求或缺陷编号，提交信息格式：[类型] #编号 简述。\n3. 功能开发完成后须发起 Code Review，至少一名同级或高级工程师审核通过。\n4. 代码合并到 develop 分支后自动触发 CI 流水线，包含：编译、单测、静态扫描。\n5. 静态扫描严重问题数为 0 方可合并。\n\n五、测试流程\n1. 测试阶段划分：单元测试 → 集成测试 → 系统测试 → 验收测试。\n2. 单元测试由开发人员编写，代码覆盖率要求不低于 60%。\n3. 系统测试由测试团队执行，严重缺陷必须全部修复后方可进入验收阶段。\n4. 缺陷等级：致命（Blocker）、严重（Critical）、一般（Major）、轻微（Minor）。\n5. 上线标准：无致命和严重缺陷', 500, 'PENDING', '2026-04-22 16:45:47');
INSERT INTO `kb_chunk` VALUES (20, 6, 2, '严重（Critical）、一般（Major）、轻微（Minor）。\n5. 上线标准：无致命和严重缺陷，一般缺陷遗留不超过 3 个且有明确修复计划。\n\n六、上线与发布\n1. 上线前须完成：上线检查清单确认、回滚方案准备、相关方通知。\n2. 生产环境发布窗口为工作日 18:00-22:00 或周末 10:00-18:00。\n3. 发布采用灰度策略：先 1% → 10% → 50% → 100%，每阶段观察 30 分钟。\n4. 发布过程中出现严重问题立即执行回滚，确保 15 分钟内恢复。\n5. 发布完成后 24 小时内为观察期，运维重点关注系统指标和用户反馈。\n\n七、项目复盘\n1. 每个项目或迭代结束后 1 周内召开复盘会议。\n2. 复盘内容：目标达成情况、做得好的方面、待改进的方面、行动计划。\n3. 复盘结论录入知识库，供后续项目参考。\n4. 行动计划需指定责任人和截止日期，在下次复盘时检查完成情况。\n\n八、项目沟通\n1. 每日站会：15 分钟内完成，每人汇报昨日完成、今日计划、阻塞问题。\n2. 周报：每周五下班前提交，内容包括本周进展、下周计划、风险预警。\n3. 里程碑会议：每个里程碑节', 500, 'PENDING', '2026-04-22 16:45:47');
INSERT INTO `kb_chunk` VALUES (21, 6, 3, '2. 周报：每周五下班前提交，内容包括本周进展、下周计划、风险预警。\n3. 里程碑会议：每个里程碑节点召开评审会，确认交付物和下阶段计划。\n4. 客户沟通：项目经理每两周向客户汇报一次项目进展，重大事项即时同步。', 106, 'PENDING', '2026-04-22 16:45:47');
INSERT INTO `kb_chunk` VALUES (22, 7, 0, '财务报销制度\n\n一、报销原则\n1. 所有费用报销须遵循\"事前审批、事后报销、真实合规\"的原则。\n2. 报销凭证必须真实有效，严禁虚假报销，一经发现按公司纪律严肃处理。\n3. 报销须在费用发生后 30 天内提交，超过 60 天原则上不予报销。\n\n二、差旅费报销标准\n2.1 交通标准\n- 总监及以上：飞机经济舱/商务舱、高铁一等座。\n- 经理级：飞机经济舱、高铁一等座。\n- 普通员工：飞机经济舱（提前 3 天以上预订）、高铁二等座。\n- 市内交通：公共交通实报实销；打车需说明原因，每天上限 200 元。\n\n2.2 住宿标准\n- 一线城市（北京、上海、广州、深圳）：总监级 800 元/晚，经理级 600 元/晚，普通员工 450 元/晚。\n- 二线城市：总监级 600 元/晚，经理级 450 元/晚，普通员工 350 元/晚。\n- 其他城市：总监级 500 元/晚，经理级 350 元/晚，普通员工 250 元/晚。\n- 两人同行同性别须拼房，标准可上浮 50%。\n\n2.3 餐饮补贴\n- 出差期间每天餐饮补贴 100 元，无需提供发票。\n- 客户招待餐费另行审批，不计入个人补贴。\n\n三、业务招', 500, 'PENDING', '2026-04-22 16:45:51');
INSERT INTO `kb_chunk` VALUES (23, 7, 1, '间每天餐饮补贴 100 元，无需提供发票。\n- 客户招待餐费另行审批，不计入个人补贴。\n\n三、业务招待费\n1. 业务招待须事前在 OA 系统提交《招待申请单》，经部门主管审批。\n2. 招待标准：普通商务餐人均不超过 200 元，重要客户人均不超过 500 元。\n3. 招待费报销须附：审批单、发票、参与人员名单、招待事由说明。\n4. 严禁以招待名义报销个人消费。\n\n四、办公用品与设备采购\n1. 日常办公用品由行政部统一采购，个人不得自行购买报销。\n2. 特殊办公设备（如显示器、键盘）需提交采购申请，500 元以下部门主管审批，500 元以上需 IT 和财务联合审批。\n3. 软件许可证和云服务费用由 IT 部门统一管理和采购。\n\n五、报销流程\n1. 员工在 OA 系统填写报销单，上传发票照片和相关审批单据。\n2. 部门主管审核：确认费用真实性和合理性。\n3. 财务审核：核对发票真伪、金额、标准合规性。\n4. 超过 5000 元的报销需财务经理审批，超过 20000 元需财务总监审批。\n5. 审批通过后 5 个工作日内打款至员工工资卡。\n\n六、发票要求\n1. 发票抬头必须为公司全称，税号正确', 500, 'PENDING', '2026-04-22 16:45:51');
INSERT INTO `kb_chunk` VALUES (24, 7, 2, '审批通过后 5 个工作日内打款至员工工资卡。\n\n六、发票要求\n1. 发票抬头必须为公司全称，税号正确。\n2. 增值税专用发票需在开票后 180 天内报销。\n3. 以下凭证不予报销：白条、收据、个人抬头发票、模糊无法辨认的发票。\n4. 电子发票须通过国税局平台验证真伪后报销。\n\n七、常见问题\nQ1: 出差标准超标了怎么办？\nA1: 特殊情况（如旺季酒店涨价、紧急出差无法提前订票）可申请超标审批，需部门总监签字。\n\nQ2: 发票丢失了怎么办？\nA2: 500 元以下可提供支付记录截图、情况说明和部门主管签字替代；500 元以上需联系商家补开。\n\nQ3: 团建费用怎么报销？\nA3: 团建须事前审批，预算内由部门统一报销，人均标准不超过 300 元/次。', 327, 'PENDING', '2026-04-22 16:45:51');
INSERT INTO `kb_chunk` VALUES (25, 8, 0, '客户常见问题 FAQ\n\n一、账户相关\n\nQ: 如何注册账户？\nA: 访问官网首页点击\"免费注册\"，填写手机号、验证码和密码即可完成注册。企业用户可选择\"企业注册\"，需额外填写企业名称和统一社会信用代码。\n\nQ: 忘记密码怎么办？\nA: 在登录页点击\"忘记密码\"，通过注册手机号接收验证码重置密码。如手机号已更换，请携带身份证联系客服人工重置。\n\nQ: 账户被锁定了怎么办？\nA: 连续 5 次输入错误密码会触发锁定，等待 30 分钟后自动解锁。如紧急使用，可联系客服提前解锁。\n\nQ: 如何修改绑定的手机号？\nA: 登录后进入\"个人中心 > 安全设置 > 修改手机号\"，需验证原手机号后方可更换。\n\nQ: 如何注销账户？\nA: 进入\"个人中心 > 账户设置 > 注销账户\"，确认无未完成订单和余额后提交申请，7 个工作日内处理完成。注销后数据不可恢复。\n\n二、产品相关\n\nQ: 你们的产品有哪些版本？\nA: 我们提供三个版本：\n- 基础版（免费）：支持 3 个用户、1GB 存储空间、基础功能。\n- 专业版（299 元/月）：支持 20 个用户、50GB 存储、高级分析和 API 接口。\n- 企业版', 500, 'PENDING', '2026-04-22 16:45:56');
INSERT INTO `kb_chunk` VALUES (26, 8, 1, '专业版（299 元/月）：支持 20 个用户、50GB 存储、高级分析和 API 接口。\n- 企业版（联系销售定价）：不限用户数、不限存储、私有化部署、专属技术支持。\n\nQ: 支持哪些操作系统？\nA: 支持 Windows 10/11、macOS 12+、主流 Linux 发行版。移动端支持 iOS 14+ 和 Android 10+。Web 版支持 Chrome、Firefox、Safari、Edge 最新两个版本。\n\nQ: 数据存储在哪里？安全吗？\nA: SaaS 版本数据存储在阿里云北京和上海双活数据中心，通过 AES-256 加密存储，TLS 1.3 加密传输。企业版支持私有化部署到客户自有服务器。我们已通过 ISO 27001 和等保三级认证。\n\nQ: 支持数据导入导出吗？\nA: 支持。可导入 CSV、Excel、JSON 格式数据。导出支持 CSV、Excel、PDF 格式。企业版额外支持 API 批量导入导出。\n\nQ: 有 API 接口吗？\nA: 专业版和企业版提供完整的 RESTful API，支持 OAuth 2.0 认证。API 文档地址：docs.company.', 500, 'PENDING', '2026-04-22 16:45:56');
INSERT INTO `kb_chunk` VALUES (27, 8, 2, 'RESTful API，支持 OAuth 2.0 认证。API 文档地址：docs.company.com/api。基础版不提供 API 接口。\n\n三、付费相关\n\nQ: 支持哪些支付方式？\nA: 支持支付宝、微信支付、银行转账、对公汇款。企业客户支持月付、季付、年付，年付享 85 折优惠。\n\nQ: 可以先试用再购买吗？\nA: 可以。专业版提供 14 天免费试用，试用期间功能无限制。试用到期后自动降级为基础版，数据保留 30 天。\n\nQ: 购买后可以退款吗？\nA: 购买后 7 天内未使用可全额退款。超过 7 天按已使用天数扣除费用后退还剩余金额。\n\nQ: 发票怎么申请？\nA: 支付成功后在\"订单中心\"点击\"申请发票\"，支持电子普通发票（即时开具）和增值税专用发票（3 个工作日开具，需提供开票信息）。\n\nQ: 如何升级或降级版本？\nA: 在\"订单中心 > 我的订阅\"中操作。升级立即生效，补差价按剩余天数折算。降级在当前计费周期结束后生效。\n\n四、技术支持\n\nQ: 遇到技术问题怎么联系你们？\nA: 基础版：在线帮助文档和社区论坛。专业版：工作日在线客服（响应时间 4 小时内）。企业版：7×2', 500, 'PENDING', '2026-04-22 16:45:56');
INSERT INTO `kb_chunk` VALUES (28, 8, 3, 'A: 基础版：在线帮助文档和社区论坛。专业版：工作日在线客服（响应时间 4 小时内）。企业版：7×24 小时专属技术顾问和电话支持（响应时间 30 分钟内）。\n\nQ: 系统崩溃了数据会丢失吗？\nA: 不会。我们每 6 小时自动备份一次，关键数据实时同步到备份集群。最坏情况下最多丢失 6 小时数据，企业版支持实时备份零丢失。\n\nQ: 你们的系统可用性是多少？\nA: SLA 承诺 99.9% 可用性（约年累计宕机时间 < 8.76 小时）。企业版 SLA 承诺 99.99%。实际运行可用性连续 3 年超过 99.95%。', 261, 'PENDING', '2026-04-22 16:45:56');
INSERT INTO `kb_chunk` VALUES (29, 9, 0, '考勤与请假制度\n\n一、工作时间\n1. 标准工作时间：周一至周五，上午 9:00 至下午 18:00，午休 12:00-13:00。\n2. 弹性工作制：研发和设计岗位可申请弹性制，核心工作时间为 10:00-16:00，日工作满 8 小时即可。\n3. 加班须提前在 OA 系统提交申请，经主管审批后方可计为有效加班。\n4. 工作日加班按 1.5 倍计薪，周末加班按 2 倍计薪，法定节假日按 3 倍计薪。也可选择调休。\n\n二、打卡规则\n1. 考勤采用人脸识别 + 手机定位双重打卡。\n2. 每天需打上班卡和下班卡，漏打卡视为缺勤。\n3. 漏打卡补卡：每月允许补卡 3 次，须在漏打卡后 24 小时内在 OA 系统申请，主管审批。\n4. 迟到定义：超过上班时间 10 分钟以上视为迟到。迟到超过 30 分钟视为旷工半天。\n5. 每月迟到 3 次以内不处罚（给予口头提醒），超过 3 次扣当月全勤奖。\n\n三、请假类型与天数\n3.1 带薪假期\n- 年假：工龄 1-10 年 5 天，10-20 年 10 天，20 年以上 15 天。\n- 婚假：3 天（晚婚增加 7 天）。\n- 产假：女员工 158 天，男员', 500, 'PENDING', '2026-04-22 16:46:00');
INSERT INTO `kb_chunk` VALUES (30, 9, 1, '20 年以上 15 天。\n- 婚假：3 天（晚婚增加 7 天）。\n- 产假：女员工 158 天，男员工陪产假 15 天。\n- 丧假：直系亲属 3 天，旁系亲属 1 天。\n- 工伤假：按实际医疗期，全额带薪。\n\n3.2 其他假期\n- 病假：需提供医院诊断证明。3 天以内扣日薪 30%，3 天以上按当地病假工资标准执行。\n- 事假：无薪假，按实际天数扣发工资。全年事假累计不超过 15 天。\n- 调休假：加班产生的调休需在 3 个月内使用完毕，过期作废。\n\n四、请假流程\n1. 请假 1 天以内：OA 系统提交，直接主管审批。\n2. 请假 1-3 天：直接主管和部门总监双审批。\n3. 请假 3 天以上：须提前 1 周申请，经部门总监和 HR 审批。\n4. 紧急请假（突发疾病等）：可先电话通知主管，事后 24 小时内补办手续。\n5. 未经批准擅自缺勤视为旷工，旷工 1 天扣 3 天工资，连续旷工 3 天以上视为自动离职。\n\n五、远程办公\n1. 符合条件的员工每月可申请不超过 4 天的居家办公。\n2. 远程办公须提前 1 天在 OA 系统申请，主管审批通过后生效。\n3. 远程办公期间须保持通讯畅通', 500, 'PENDING', '2026-04-22 16:46:00');
INSERT INTO `kb_chunk` VALUES (31, 9, 2, '. 远程办公须提前 1 天在 OA 系统申请，主管审批通过后生效。\n3. 远程办公期间须保持通讯畅通，在核心工作时间内可随时联系。\n4. 远程办公不影响考勤记录，通过 VPN 登录内部系统自动计为出勤。\n\n六、特殊情况\n1. 恶劣天气（台风、暴雪红色预警）：公司统一通知是否停工或远程办公。\n2. 公共卫生事件：按政府和公司防疫要求执行，期间考勤政策另行通知。\n3. 出差期间：考勤以出差审批单为准，无需打卡。\n\n七、常见问题\nQ1: 年假可以跨年使用吗？\nA1: 当年未休年假可顺延至次年 3 月 31 日前使用，过期作废，不折算工资。\n\nQ2: 哺乳期有什么考勤优待？\nA2: 孩子 1 周岁内，每天可享受 1 小时哺乳假，可提前下班或推迟上班。\n\nQ3: 全勤奖怎么算？\nA3: 当月无迟到、早退、旷工、事假记录，即可获得全勤奖 300 元/月。病假 1 天以内不影响全勤。', 390, 'PENDING', '2026-04-22 16:46:00');

-- ----------------------------
-- Table structure for kb_document
-- ----------------------------
DROP TABLE IF EXISTS `kb_document`;
CREATE TABLE `kb_document`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文档ID',
  `file_id` bigint NULL DEFAULT NULL COMMENT '关联文件ID',
  `document_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文档名称',
  `source_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'MANUAL' COMMENT '来源类型',
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文档分类',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签',
  `content_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内容类型',
  `parse_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '解析状态',
  `embedding_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '向量化状态',
  `chunk_count` int NOT NULL DEFAULT 0 COMMENT '切片数量',
  `enabled` tinyint NOT NULL DEFAULT 1 COMMENT '是否启用(参与检索)',
  `version` int NOT NULL DEFAULT 1 COMMENT '当前版本号',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文档摘要',
  `uploaded_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上传人',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_file_id`(`file_id` ASC) USING BTREE,
  INDEX `idx_category`(`category` ASC) USING BTREE,
  INDEX `idx_parse_status`(`parse_status` ASC) USING BTREE,
  INDEX `idx_embedding_status`(`embedding_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '知识库文档表' ROW_FORMAT = Dynamic;

