INSERT INTO `ticket` VALUES (1, 'TK2026042246552', '入职当天流程是什么', '入职当天流程是什么', '张三', '', 'MEDIUM', 'RESOLVED', '客户咨询新员工入职当天的具体流程安排，属于常规的入职手续咨询。', '尊敬的同事，您好！', '1. **核实信息**：确认该员工所属部门、职位及预定的入职日期。\n2. **提供具体流程**：\n   - 若公司有标准入职流程文档，可直接发送给客户。\n   - 如无通用文档，则联系HR部门或该员工直属团队，获取当天具体安排（如报到时间、地点、联系人、所需材料等）。\n3. **跟进确认**：将整理好的信息回复客户，并提醒其携带必要材料（如身份证、学历证明等）。\n4. **内部同步**：如该部门入职流程不明确，可建议HR优化入职指引文档或建立标准化通知模板。', '', '2026-04-22 16:50:41', '2026-04-22 16:57:40');

